export function useUpdate() {
  const [available, setAvailable] = useState(false);
  const check = async () => setAvailable(await bridge.checkUpdate());
  useEffect(() => { check(); }, []);
  return {available, check};
}

export function Toolbar() {
  const {check} = useUpdate();
  return <button onClick={check}>Check for updates</button>;
}

export function UpdateBadge() {
  const {available} = useUpdate();
  return available ? <span>Update ready</span> : null;
}
